// tb_aagm_gate.v
// Testbench for the AAGM terminal-event policy (aagm_gate.v).
//
// By default the testbench runs the built-in vector suite. It can also
// replay a vector file generated by the Python reference model:
//
//     vvp aagm_gate.vvp +vectors=vectors.txt
//
// That mode is a genuine cross-check: the expectations in the file come
// from an independent implementation of the contract, so a disagreement
// between the RTL and the reference model fails the build.

`timescale 1ns / 1ps

module tb_aagm_gate;
    reg         step_valid;
    reg         min_steps_reached;
    reg         budget_exhausted;
    reg         async_abort;
    reg  [17:0] halting_mass_q15;
    wire        halt;
    wire        halt_budget;
    wire        abort;
    wire [1:0]  halt_reason;
    integer     failures;
    integer     checks;

    aagm_gate dut (
        .step_valid(step_valid),
        .min_steps_reached(min_steps_reached),
        .budget_exhausted(budget_exhausted),
        .async_abort(async_abort),
        .halting_mass_q15(halting_mass_q15),
        .halt(halt),
        .halt_budget(halt_budget),
        .abort(abort),
        .halt_reason(halt_reason)
    );

    task run_vector;
        input [8*64-1:0] name;
        input             v_sv;
        input             v_ms;
        input             v_be;
        input             v_aa;
        input [31:0]      v_mass;
        input             v_eh;
        input             v_eb;
        input             v_ea;
        input [1:0]       v_er;
        begin
            step_valid        = v_sv;
            min_steps_reached = v_ms;
            budget_exhausted  = v_be;
            async_abort       = v_aa;
            halting_mass_q15  = v_mass[17:0];
            #1;
            checks = checks + 1;
            if (halt !== v_eh || halt_budget !== v_eb ||
                abort !== v_ea || halt_reason !== v_er) begin
                $display("FAIL %0s: halt=%b/%b budget=%b/%b abort=%b/%b reason=%b/%b",
                         name, halt, v_eh, halt_budget, v_eb,
                         abort, v_ea, halt_reason, v_er);
                failures = failures + 1;
            end
        end
    endtask

    // ---- Optional vector-file replay ---------------------------------------
    reg [8*256-1:0] vecfile;
    reg [8*256-1:0] line;
    reg [8*64-1:0]  vname;
    integer fd, r, n;
    integer v_sv, v_ms, v_be, v_aa, v_eh, v_eb, v_ea, v_er, v_mass;

    task run_vector_file;
        begin
            fd = $fopen(vecfile, "r");
            if (fd == 0) begin
                $display("ERROR: cannot open vector file %0s", vecfile);
                $fatal(1, "AAGM gate vector file not found");
            end
            while (!$feof(fd)) begin
                r = $fgets(line, fd);
                if (r != 0) begin
                    n = $sscanf(line, "%d %d %d %d %d %d %d %d %d %s",
                                v_sv, v_ms, v_be, v_aa, v_mass,
                                v_eh, v_eb, v_ea, v_er, vname);
                    if (n == 10) begin
                        run_vector(vname, v_sv, v_ms, v_be, v_aa, v_mass,
                                   v_eh, v_eb, v_ea, v_er[1:0]);
                    end
                end
            end
            $fclose(fd);
        end
    endtask

    initial begin
        $dumpfile("aagm_gate.vcd");
        $dumpvars(0, tb_aagm_gate);
        failures = 0;
        checks = 0;
        step_valid = 0; min_steps_reached = 1; budget_exhausted = 0;
        async_abort = 0; halting_mass_q15 = 18'd30000;

        if ($value$plusargs("vectors=%s", vecfile)) begin
            $display("[TIME %0tps] Replaying reference-model vectors from %0s", $time, vecfile);
            run_vector_file;
        end else begin
            $display("[TIME %0tps] Running the built-in vector suite", $time);
            run_vector("Idle_step_valid_0",        0, 1, 0, 0, 30000,  0, 0, 0, 2'b00);
            run_vector("Min_steps_not_reached",     1, 0, 0, 0, 30000,  0, 0, 0, 2'b00);
            run_vector("Mass_just_below_threshold", 1, 1, 0, 0, 29490,  0, 0, 0, 2'b00);
            run_vector("Mass_at_threshold",         1, 1, 0, 0, 29491,  1, 0, 0, 2'b01);
            run_vector("Mass_far_above_threshold",  1, 1, 0, 0, 131072, 1, 0, 0, 2'b01);
            run_vector("Budget_exhausted",          1, 1, 1, 0, 29491,  0, 1, 0, 2'b10);
            run_vector("Budget_and_min_steps",      1, 0, 1, 0, 29491,  0, 1, 0, 2'b10);
            run_vector("Abort_exclusive",           1, 1, 0, 1, 29491,  0, 0, 1, 2'b11);
            run_vector("Abort_suppresses_act",      1, 1, 0, 1, 131072, 0, 0, 1, 2'b11);
            run_vector("Abort_without_step",        0, 1, 0, 1, 30000,  0, 0, 1, 2'b11);
            run_vector("Abort_and_budget",          1, 1, 1, 1, 29491,  0, 0, 1, 2'b11);
            run_vector("No_terminal_event",         1, 1, 0, 0, 1000,   0, 0, 0, 2'b00);
        end

        if (failures == 0)
            $display(">>> AAGM_VERILOG_PASS (%0d checks, Gate logic verified)", checks);
        else
            $display(">>> AAGM_VERILOG_FAIL count=%0d", failures);
        if (failures != 0) $fatal(1, "AAGM Verilog checks failed");
        $finish;
    end
endmodule
